import{_ as s,o as a,c as t,a3 as i}from"./chunks/framework.D0WMbOy-.js";const k=JSON.parse('{"title":"Manage datasets","description":"","frontmatter":{},"headers":[],"relativePath":"guide/datasets.md","filePath":"guide/datasets.md","lastUpdated":1793437233000}'),n={name:"guide/datasets.md"};function o(d,e,r,h,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="manage-datasets" tabindex="-1">Manage datasets <a class="header-anchor" href="#manage-datasets" aria-label="Permalink to &quot;Manage datasets&quot;">​</a></h1><p>Boomerangz reads policy from locally configured <code>org.boomerangz:*</code> ZFS user properties. A dataset remains unmanaged until <code>org.boomerangz:enabled=on</code> applies to it.</p><h2 id="inspect-before-changing" tabindex="-1">Inspect before changing <a class="header-anchor" href="#inspect-before-changing" aria-label="Permalink to &quot;Inspect before changing&quot;">​</a></h2><p>List discovered datasets and inspect one effective policy:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>These commands are read-only and produce human-readable output by default. <code>dataset list</code> labels each dataset as one of:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>active</code></td><td>an actor root: enabled, with no enabled ancestor</td></tr><tr><td><code>member</code></td><td>inside a root&#39;s subtree and managed by that root</td></tr><tr><td><code>excluded</code></td><td>inside a root&#39;s subtree but left out of it</td></tr><tr><td><code>target</code></td><td>a replica Boomerangz receives into, or part of one</td></tr><tr><td><code>inactive</code></td><td>not enabled, not inside any root, and not a replica</td></tr><tr><td><code>invalid</code></td><td>its policy has errors; inspect it for the reported errors</td></tr></tbody></table><p>A root with a destination blocked by a collision stays <code>active</code>; <code>dataset list</code> names the blocked destination beside it.</p><p>A dataset reads as <code>target</code> when an actor root on this host places its replica there on a local destination, when it carries a source root&#39;s lineage received with a stream that sent properties, or when it lies beneath one of this host&#39;s <code>replication_roots</code>; anything beneath such a dataset is part of the same replica. <code>dataset inspect</code> says which of these marks it. A replica on another host, or one received without properties beneath a root this host is not configured to receive into, still reads as <code>inactive</code>.</p><p><code>dataset list</code> leaves inactive datasets out, and says how many it hid. Show only the statuses you want with <code>--status</code>, repeated or comma-separated, and every dataset with <code>--status all</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> active,member</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span></code></pre></div><p><code>dataset inspect</code> shows activation and validation status, the actor root the dataset belongs to, what marks it as a replica and, for a root, its members and blocked destinations, together with the effective policy, property provenance, warnings, and errors.</p><p>Add <code>--json</code> when a script or other structured consumer needs the stable JSON representation:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="set-a-snapshot-policy" tabindex="-1">Set a snapshot policy <a class="header-anchor" href="#set-a-snapshot-policy" aria-label="Permalink to &quot;Set a snapshot policy&quot;">​</a></h2><p>A policy is a comma-separated grid of <code>count x duration</code> tiers:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:policy=12x5m,24x1h,14x1d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>The shortest duration is the snapshot cadence. In this example Boomerangz takes a snapshot every five minutes, keeps progressively fewer snapshots as they age, and retains coverage through the daily tier.</p><p>Supported duration units are:</p><table tabindex="0"><thead><tr><th>Unit</th><th>Meaning</th></tr></thead><tbody><tr><td><code>m</code></td><td>minute</td></tr><tr><td><code>h</code></td><td>hour</td></tr><tr><td><code>d</code></td><td>24-hour day</td></tr><tr><td><code>w</code></td><td>seven days</td></tr><tr><td><code>mo</code></td><td>30 days</td></tr><tr><td><code>y</code></td><td>365 days</td></tr></tbody></table><p>These are elapsed durations rather than calendar boundaries. For example, <code>12mo</code> is 360 days and is not the same duration as <code>1y</code>.</p><h2 id="roots-and-members" tabindex="-1">Roots and members <a class="header-anchor" href="#roots-and-members" aria-label="Permalink to &quot;Roots and members&quot;">​</a></h2><p>ZFS properties normally pass from a parent dataset to its children, and <code>enabled</code> is no exception. Enabling a dataset makes it an <strong>actor root</strong>, and it owns its whole subtree:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:policy=24x1h,14x1d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home</span></span></code></pre></div><p>A dataset is an actor root when it is enabled and no ancestor is. Every enabled dataset beneath a root is one of its <strong>members</strong>, not a root of its own: the root&#39;s lineage, target bindings, recovery state and jobs cover all of them, and members carry no Boomerangz state themselves.</p><p>Set <code>org.boomerangz:enabled=off</code> locally on a child to exclude it and everything that inherits from it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=off</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home/.cache</span></span></code></pre></div><p>An exclusion does not sever deeper datasets from the root. Setting <code>enabled=on</code> again further down makes that dataset a member of the same root, with a hole at the excluded dataset in between:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=off</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home/projects</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home/projects/current</span></span></code></pre></div><p>Nothing is snapshotted or sent for a hole, but its name is created at each destination as an empty placeholder so the deeper member can be received beneath it. If the hole is included again later, its own replica replaces the placeholder and the replicas beneath move under it with their history. The same happens when a root starts sending to a destination only its members used before. This needs the <code>rename</code> permission on the destination.</p><p>Each member keeps its own retention grid, send options, incremental mode, receive overrides and destinations, including destinations its root does not use. A root snapshots exactly the members that are due, atomically, and prunes each against its own grid, so a <code>14x1d</code> member is not snapshotted every five minutes because its root is. The receive path mapping (<code>discard</code>) and the wire format (<code>replicate</code>) belong to the root: a member that sets either gets a warning and follows its root.</p><p>A member&#39;s replica lands beneath its root&#39;s, which under the default <code>discard=off</code> is a remote&#39;s configured root itself. A remote never creates its configured root except by receiving the root&#39;s own replica, so a member that sends to a remote its root does not use needs that configured root to exist already. Until it does, the member&#39;s transfer stops and says to create it on the remote or to add the remote to the root.</p><p>Operate on the root, not on a member. <code>dataset adopt</code>, <code>dataset reseed</code> and <code>trigger</code> refuse a member or excluded dataset and name its root. A reseed of the root resets every member&#39;s replica and recovery state on that target at once.</p><p>Inspect parents and children before enabling a broad root.</p><h2 id="add-destinations" tabindex="-1">Add destinations <a class="header-anchor" href="#add-destinations" aria-label="Permalink to &quot;Add destinations&quot;">​</a></h2><p>Select configured remote destinations by name:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:discard=first</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:remote=home-backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tank/data</span></span></code></pre></div><p>For a destination dataset on the same host:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:discard=first</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:local=backup/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tank/data</span></span></code></pre></div><p><code>first</code> is recommended when the configured local or remote root is a persistent destination container. The default <code>off</code> instead treats that configured path as the exact, replica-owned receive dataset; it must initially be absent and its receive permissions must be delegated on the parent. Review the <a href="/development/reference/properties#receive-path-mapping">receive path mapping</a> before selecting a destination.</p><p>Multiple names are comma-separated. Empty entries and unknown remote names make the affected policy invalid. Configure and secure the destination before selecting it.</p><p>Each root&#39;s replica on a destination must be its own. If two roots&#39; replicas would overlap - <code>tank/a/data</code> and <code>tank/b/data</code> both under <code>discard=all</code>, say, or one root&#39;s two destinations nested inside each other - that destination is blocked for the roots involved: nothing is sent there, and <code>dataset reseed</code> and <code>dataset abort-receive</code> refuse it. Only the destination stops. Each root stays <code>active</code>, keeps snapshotting and pruning, and keeps sending to its other destinations. <code>dataset list</code> shows blocked destinations beside the root, and <code>dataset inspect</code> names what each collides with.</p><p>A replica a root has already established - one its stored binding proves - keeps its destination, and only the newly configured root that would overlap it is blocked, so a mistake in new configuration cannot stop a working backup. When neither side, or both, has an established replica there, both are blocked. A local destination inside an active root is blocked the same way, because the received replicas would become that root&#39;s members. Two remotes collide when they reach the same host&#39;s pools, whatever account they connect as.</p><p>A remote that turns out to receive into one of this host&#39;s own pools - an SSH remote addressed back at this machine, say - is recognised by its pool&#39;s GUID the first time it is reached, before anything is received. Its replicas are then checked like a local destination&#39;s, against this host&#39;s actor roots and local replicas, and the transfer goes ahead only if that destination is not blocked. <code>dataset list</code> and <code>dataset inspect</code> do not connect to remotes, so they cannot show this case; the daemon reports it, and so does <code>dataset reseed</code>.</p><h2 id="recursive-replication" tabindex="-1">Recursive replication <a class="header-anchor" href="#recursive-replication" aria-label="Permalink to &quot;Recursive replication&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:replicate=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>Without <code>replicate</code>, a root sends each member as a stream of its own, with that member&#39;s send options. With <code>replicate=on</code> the root sends its whole subtree as one <code>zfs send -R</code> package instead: every descendant becomes a member, on the root&#39;s grid and with the root&#39;s send options, and descendants&#39; <code>org.boomerangz:*</code> properties are ignored with a warning.</p><p><code>replicate=on</code> cannot exclude anything. A descendant with <code>enabled=off</code> is still in the package, and gets a warning of its own saying so. Recursive replication can also carry snapshots not created by Boomerangz, and receive behavior can remove destination snapshots that are absent from the source package. Enable it only after reviewing the complete hierarchy and testing the destination mapping.</p><p>Turning <code>replicate=on</code> for a root that already replicated member by member needs a <a href="/development/operations/recovery#reseed-a-target">reseed</a> of each of its targets: holes and excluded datasets were never sent, so the recursive package has no common base to continue from. The transfer says so before changing anything. Turning <code>replicate</code> off again needs nothing: every member&#39;s replica already shares a snapshot with its source, and each continues incrementally on its own stream. Replicas of datasets that are no longer members stay on the destination untouched.</p><h2 id="deactivate-a-dataset" tabindex="-1">Deactivate a dataset <a class="header-anchor" href="#deactivate-a-dataset" aria-label="Permalink to &quot;Deactivate a dataset&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=off</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>Deactivating a root stops new management of its whole subtree but does not immediately remove recovery state. By default, the root remains recoverable for 24 hours before automatic retirement becomes eligible; retirement then covers every dataset beneath it. Change that delay with <code>daemon.inactive_grace_period</code>; set it to <code>0s</code> to disable automatic retirement.</p><p>Re-enable the root during the grace period to resume management without discarding its established history.</p><p>Excluding a member instead only stops new snapshots of it. It has no recovery state of its own to retire: the snapshots it already holds stay under its own grid, keeping the newest few, and go when its root retires. Re-enabling it makes it a member again with its history intact.</p><p>See the <a href="/development/reference/properties">property reference</a> for every available setting.</p>`,55)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
